import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { FiX, FiEdit2, FiSave, FiUser, FiMail, FiPhone, FiCalendar } from "react-icons/fi";
import { toast } from "react-toastify";
import { useAuth } from "../../../auth/model/AuthContext";

export default function MyProfileModal({ isOpen, onClose }) {
  const { user, updateProfile } = useAuth();

  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    phoneNumber: "",
  });

  useEffect(() => {
    if (user && isOpen) {
      setFormData({
        fullName: user.fullName || "",
        phoneNumber: user.phoneNumber || "",
      });
      setIsEditing(false);
    }
  }, [user, isOpen]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSave = async () => {
    if (!formData.fullName.trim()) {
      toast.error("Full Name cannot be empty.");
      return;
    }

    setLoading(true);
    try {
      await updateProfile(formData);
      toast.success("Profile updated successfully!");
      setIsEditing(false);
    } catch (err) {
      toast.error(err.message || "Failed to update profile.");
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return "N/A";
    const date = new Date(dateString);
    return new Intl.DateTimeFormat("en-US", {
      month: "short",
      day: "numeric",
      year: "numeric",
    }).format(date);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 sm:p-6">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm"
            onClick={onClose}
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 20 }}
            className="relative w-full max-w-lg overflow-hidden rounded-3xl bg-white shadow-2xl"
          >
            <div className="flex items-center justify-between border-b border-slate-100 px-6 py-5 bg-slate-50/50">
              <h3 className="text-xl font-extrabold text-slate-900">My Profile</h3>
              <button
                onClick={onClose}
                className="flex h-8 w-8 items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-slate-200 hover:text-slate-700"
              >
                <FiX className="text-xl" />
              </button>
            </div>

            <div className="px-6 py-6 space-y-5">
              {/* Full Name */}
              <div>
                <label className="mb-1.5 flex items-center gap-2 text-sm font-bold text-slate-700">
                  <FiUser className="text-slate-400" />
                  Full Name
                </label>
                {isEditing ? (
                  <input
                    type="text"
                    name="fullName"
                    value={formData.fullName}
                    onChange={handleChange}
                    className="w-full rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-slate-900 outline-none transition-all focus:border-[#006b58] focus:ring-4 focus:ring-[#006b58]/10"
                    placeholder="Enter your full name"
                  />
                ) : (
                  <p className="rounded-xl bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-900">
                    {user?.fullName || "Not provided"}
                  </p>
                )}
              </div>

              {/* Email (Read Only) */}
              <div>
                <label className="mb-1.5 flex items-center gap-2 text-sm font-bold text-slate-700">
                  <FiMail className="text-slate-400" />
                  Email Address
                </label>
                <p className="rounded-xl bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-500 cursor-not-allowed">
                  {user?.email}
                </p>
                <p className="mt-1 text-xs text-slate-400">Email cannot be changed.</p>
              </div>

              {/* Phone Number */}
              <div>
                <label className="mb-1.5 flex items-center gap-2 text-sm font-bold text-slate-700">
                  <FiPhone className="text-slate-400" />
                  Phone Number
                </label>
                {isEditing ? (
                  <input
                    type="text"
                    name="phoneNumber"
                    value={formData.phoneNumber}
                    onChange={handleChange}
                    className="w-full rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-medium text-slate-900 outline-none transition-all focus:border-[#006b58] focus:ring-4 focus:ring-[#006b58]/10"
                    placeholder="Enter your phone number"
                  />
                ) : (
                  <p className="rounded-xl bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-900">
                    {user?.phoneNumber || "Not provided"}
                  </p>
                )}
              </div>

              {/* Joined Date */}
              <div>
                <label className="mb-1.5 flex items-center gap-2 text-sm font-bold text-slate-700">
                  <FiCalendar className="text-slate-400" />
                  Joined Date
                </label>
                <p className="rounded-xl bg-slate-50 px-4 py-2.5 text-sm font-semibold text-slate-900">
                  {formatDate(user?.createdAt)}
                </p>
              </div>
            </div>

            <div className="flex items-center justify-end gap-3 border-t border-slate-50 bg-slate-50/50 px-6 py-4">
              {isEditing ? (
                <>
                  <button
                    type="button"
                    onClick={() => {
                      setIsEditing(false);
                      setFormData({
                        fullName: user?.fullName || "",
                        phoneNumber: user?.phoneNumber || "",
                      });
                    }}
                    className="rounded-xl px-5 py-2.5 text-sm font-bold text-slate-600 transition-colors hover:bg-slate-200/50"
                  >
                    Cancel
                  </button>
                  <button
                    type="button"
                    onClick={handleSave}
                    disabled={loading}
                    className="inline-flex min-w-[100px] items-center justify-center gap-2 rounded-xl bg-[#006b58] px-5 py-2.5 text-sm font-bold text-white shadow-sm transition-all hover:bg-[#005243] active:scale-95 disabled:cursor-not-allowed disabled:bg-slate-300"
                  >
                    {loading ? (
                      <div className="h-5 w-5 animate-spin rounded-full border-2 border-white border-t-transparent" />
                    ) : (
                      <>
                        <FiSave className="text-lg" />
                        Save Changes
                      </>
                    )}
                  </button>
                </>
              ) : (
                <button
                  type="button"
                  onClick={() => setIsEditing(true)}
                  className="inline-flex items-center gap-2 rounded-xl bg-[#006b58] px-5 py-2.5 text-sm font-bold text-white shadow-sm transition-all hover:bg-[#005243] active:scale-95"
                >
                  <FiEdit2 className="text-lg" />
                  Edit Profile
                </button>
              )}
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}
